import{_ as a,o as e,c as t,aw as i}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Crypto Wallet","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common2/blockchain/crypto-wallet/crypto-wallet.md","filePath":"wiki/dev-commit/common2/blockchain/crypto-wallet/crypto-wallet.md"}'),o={name:"wiki/dev-commit/common2/blockchain/crypto-wallet/crypto-wallet.md"};function r(n,l,s,c,d,h){return e(),t("div",null,[...l[0]||(l[0]=[i('<h1 id="crypto-wallet" tabindex="-1">Crypto Wallet <a class="header-anchor" href="#crypto-wallet" aria-label="Permalink to &quot;Crypto Wallet&quot;">​</a></h1><ul><li><strong>Crypto Wallet</strong> (криптокошелёк) - физически НЕ хранят криптовалюту и НЕ отправляют крипто-токены, вместо этого у кошелька есть ключи к криптовалюте, которая хранятся в общедоступных сетях Blockchain</li></ul><h2 id="задачи" tabindex="-1">Задачи <a class="header-anchor" href="#задачи" aria-label="Permalink to &quot;Задачи&quot;">​</a></h2><ol><li>Предоставляют интерфейс для управления криптовалютными балансами</li><li>Предоставляют цифровые подписи, авторизующие каждую транзакцию</li><li>Хранят Public Key и Private Key, необходимые для покупки криптовалюты</li><li>Некоторые кошельки позволяют выполнять операции с криптовалютой: покупать, продавать, взаимодействовать с децентрализованными приложениями Decentralised Applications (dApps)</li></ol><h2 id="открытыи-и-закрытыи-ключ" tabindex="-1">Открытый и закрытый ключ <a class="header-anchor" href="#открытыи-и-закрытыи-ключ" aria-label="Permalink to &quot;Открытый и закрытый ключ&quot;">​</a></h2><ul><li><strong>Public Key</strong> (открытый ключ) - подобен номеру банковского счета и может широко распространяться</li><li>Позволяет пользователям получать транзакции криптокошелька</li></ul><hr><ul><li><strong>Private Key</strong> (закрытый ключ) - подобен паролю банковского счета или PIN-коду и должен храниться в секрете</li><li>Private Key пользователя подтверждает право собственности на соответствующий Public Key</li></ul><hr><ul><li>Каждый Public Key связан с одним соответствующим Private Key: вместе они используются для шифрования и расшифровки данных</li><li>При отправке токенов Private Key пользователя подписывает транзакцию и передает ее в сеть Blockchain</li></ul><h2 id="типы-кошельков" tabindex="-1">Типы кошельков <a class="header-anchor" href="#типы-кошельков" aria-label="Permalink to &quot;Типы кошельков&quot;">​</a></h2><h3 id="hot-wallet" tabindex="-1">Hot Wallet <a class="header-anchor" href="#hot-wallet" aria-label="Permalink to &quot;Hot Wallet&quot;">​</a></h3><ul><li><strong>Hot Wallet</strong> (горячие кошельки) - подключены к Интернету</li><li>Private Key хранятся и шифруются в самом приложении, которое хранится в сети</li></ul><h4 id="примеры" tabindex="-1">Примеры <a class="header-anchor" href="#примеры" aria-label="Permalink to &quot;Примеры&quot;">​</a></h4><ul><li>Web-based wallets</li><li>Mobile wallets</li><li>Desktop wallets</li></ul><h3 id="cold-wallet" tabindex="-1">Cold Wallet <a class="header-anchor" href="#cold-wallet" aria-label="Permalink to &quot;Cold Wallet&quot;">​</a></h3><ul><li><strong>Cold Wallet</strong> (холодные кошельки) - находятся в автономном режиме</li></ul><h4 id="примеры-1" tabindex="-1">Примеры <a class="header-anchor" href="#примеры-1" aria-label="Permalink to &quot;Примеры&quot;">​</a></h4><ul><li>Paper wallet - физическое место, где ключи пользователя записываются или распечатываются</li><li>Hardware wallet - внешний девайс (обычно устройство USB или Bluetooth), в котором хранятся ключи пользователя. Пользователь может подписать транзакцию, только нажав физическую кнопку на устройстве</li></ul><h3 id="custodial" tabindex="-1">Custodial <a class="header-anchor" href="#custodial" aria-label="Permalink to &quot;Custodial&quot;">​</a></h3><ul><li><strong>Custodial</strong> - большинство сетевых криптокошельков, как правило, являются кастодиальными кошельками. Обычно предлагаемые на биржах криптовалюты</li><li>Пользователи больше не имеют полного контроля над своими токенами, а Private Key, необходимые для подписи транзакций, хранятся только на бирже</li></ul><h3 id="non-custodial" tabindex="-1">Non-Custodial <a class="header-anchor" href="#non-custodial" aria-label="Permalink to &quot;Non-Custodial&quot;">​</a></h3><ul><li><strong>Non-Custodial</strong> - Private Key хранится локально у пользователя</li><li>Пользователя просят записать и безопасно сохранить список из 12 случайно сгенерированных слов, известных как recovery (восстановление), seed (начальное число) или mnemonic phrase (мнемоническая фраза)</li><li>Аппаратные кошельки по своей сути не связаны с хранением, поскольку закрытые ключи хранятся на самом устройстве</li></ul><h3 id="nft-wallet" tabindex="-1">NFT Wallet <a class="header-anchor" href="#nft-wallet" aria-label="Permalink to &quot;NFT Wallet&quot;">​</a></h3><ul><li><strong>NFT Wallet</strong> - кошельки для ханения NFT</li><li>Для кошельков NFT существует два основных варианта: Hardware wallets (аппаратные) или Software-based wallets (программные)</li></ul>',25)])])}const b=a(o,[["render",r]]);export{m as __pageData,b as default};
